import { useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import {
  Area,
  AreaChart,
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  fetchDataRange,
  fetchDirectionRoutes,
  fetchPrediction,
  fetchPredictionCompare,
  fetchPredictionMeta,
  fetchPredictionOptions,
  fetchPublicConfig,
  fetchTraffic,
} from "./api/client";
import "./App.css";

const MAP_DEFAULT = { center: [106.506145, 29.639573], zoom: 16.8 };
const RISK_COLORS = {
  low: "#22c55e",
  medium: "#f59e0b",
  high: "#fb7185",
  critical: "#f43f5e",
};

function toInputTime(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (part) => `${part}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function toApiTime(value) {
  return value ? value.replace("T", " ") : undefined;
}

function addMinutes(value, minutes) {
  const date = new Date(value);
  return toInputTime(new Date(date.getTime() + minutes * 60000));
}

function formatShortTime(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "--:--";
  return `${`${date.getHours()}`.padStart(2, "0")}:${`${date.getMinutes()}`.padStart(2, "0")}`;
}

function formatFullTime(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "--";
  const pad = (part) => `${part}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function average(values) {
  if (!values.length) return 0;
  return values.reduce((sum, item) => sum + item, 0) / values.length;
}

function inferRisk(avgVehicleCount, avgSpeed) {
  if (avgVehicleCount >= 70 || avgSpeed <= 15) return "critical";
  if (avgVehicleCount >= 50 || avgSpeed <= 22) return "high";
  if (avgVehicleCount >= 28 || avgSpeed <= 30) return "medium";
  return "low";
}

function riskLabel(level) {
  return {
    low: "低风险",
    medium: "中风险",
    high: "高风险",
    critical: "严重",
  }[level];
}

function normalizeDirection(direction) {
  return direction || "未指定";
}

function buildSiteSummaries(rows, intersections) {
  const grouped = new Map();
  rows.forEach((row) => {
    const current = grouped.get(row.site_name) || {
      siteName: row.site_name,
      vehicleValues: [],
      speedValues: [],
      directions: new Set(),
    };
    current.vehicleValues.push(Number(row.vehicle_count) || 0);
    current.speedValues.push(Number(row.avg_speed) || 0);
    current.directions.add(normalizeDirection(row.approach));
    grouped.set(row.site_name, current);
  });

  const fallback = intersections.map((item) => item.site_name);
  const names = grouped.size ? Array.from(grouped.keys()) : fallback;

  return names
    .map((name) => {
      const source = grouped.get(name) || {
        siteName: name,
        vehicleValues: [],
        speedValues: [],
        directions: new Set(),
      };
      const avgVehicleCount = Math.round(average(source.vehicleValues));
      const avgSpeed = Number(average(source.speedValues).toFixed(1));
      const risk = inferRisk(avgVehicleCount, avgSpeed || 40);
      return {
        siteName: name,
        avgVehicleCount,
        avgSpeed,
        risk,
        directions: Array.from(source.directions),
      };
    })
    .sort((a, b) => {
      const order = ["critical", "high", "medium", "low"];
      return order.indexOf(a.risk) - order.indexOf(b.risk) || b.avgVehicleCount - a.avgVehicleCount;
    });
}

function buildMonitorRows(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const key = `${row.site_name}|${row.approach}`;
    const current = grouped.get(key) || {
      siteName: row.site_name,
      direction: normalizeDirection(row.approach),
      vehicleValues: [],
      speedValues: [],
    };
    current.vehicleValues.push(Number(row.vehicle_count) || 0);
    current.speedValues.push(Number(row.avg_speed) || 0);
    grouped.set(key, current);
  });

  return Array.from(grouped.values())
    .map((item) => {
      const avgVehicleCount = Math.round(average(item.vehicleValues));
      const avgSpeed = Number(average(item.speedValues).toFixed(1));
      return {
        ...item,
        avgVehicleCount,
        avgSpeed,
        risk: inferRisk(avgVehicleCount, avgSpeed),
      };
    })
    .sort((a, b) => {
      const order = ["critical", "high", "medium", "low"];
      return order.indexOf(a.risk) - order.indexOf(b.risk) || b.avgVehicleCount - a.avgVehicleCount;
    });
}

function buildPredictionStats(rows) {
  if (!rows.length) {
    return { peak: 0, low: 0, avg: 0, peakTime: "--:--" };
  }
  const values = rows.map((item) => Number(item.predicted_vehicle_count) || 0);
  const peak = Math.max(...values);
  const low = Math.min(...values);
  const avg = Math.round(average(values));
  const peakRow = rows.find((item) => (Number(item.predicted_vehicle_count) || 0) === peak);
  return {
    peak,
    low,
    avg,
    peakTime: peakRow ? formatShortTime(peakRow.timestamp) : "--:--",
  };
}

function buildEffectSeries(predictionRows, interventions) {
  const factor = interventions.length
    ? interventions.reduce((sum, item) => sum + (item.effectFactor || 0), 0)
    : 0;

  return predictionRows.map((item, index) => {
    const before = Number(item.predicted_vehicle_count) || 0;
    const scale = Math.max(0.75, 1 - factor - index * 0.01);
    const after = Math.round(before * scale);
    return { time: formatShortTime(item.timestamp), before, after };
  });
}

function buildInterventions(siteSummary, selectedDirection, predictionStats) {
  if (!siteSummary) return [];
  const direction = selectedDirection || siteSummary.directions[0] || "主方向";
  const risk = siteSummary.risk;
  const suggestions = [];

  if (risk === "critical" || risk === "high") {
    suggestions.push({
      id: `${siteSummary.siteName}-signal`,
      title: "延长信号放行窗口",
      target: `${siteSummary.siteName} · ${direction}`,
      priority: risk === "critical" ? "高" : "中",
      reason: "当前车流偏高且速度下降，存在排队扩散风险。",
      expected: `预计峰值下降 ${risk === "critical" ? 12 : 8}%`,
      effectFactor: risk === "critical" ? 0.12 : 0.08,
    });
  }

  if (predictionStats.peak >= 45) {
    suggestions.push({
      id: `${siteSummary.siteName}-diversion`,
      title: "提前分流周边车流",
      target: `${siteSummary.siteName} · ${direction}`,
      priority: "高",
      reason: `预计 ${predictionStats.peakTime} 出现峰值车流，建议提前引导绕行。`,
      expected: "预计平均车速提升 6%",
      effectFactor: 0.06,
    });
  }

  suggestions.push({
    id: `${siteSummary.siteName}-notify`,
    title: "联动车主端推送提醒",
    target: `${siteSummary.siteName} · ${direction}`,
    priority: "中",
    reason: "向用户端提前发送避堵提示，可降低瞬时汇入压力。",
    expected: "预计拥堵指数下降 5%",
    effectFactor: 0.05,
  });

  return suggestions.slice(0, 3);
}

function buildPredictionSeries(predictionRows) {
  return predictionRows.map((item) => ({
    time: formatShortTime(item.timestamp),
    predicted: Number(item.predicted_vehicle_count) || 0,
  }));
}

function getWeatherSummary(rows) {
  if (!rows.length) return "天气待同步";
  const grouped = new Map();
  rows.forEach((row) => {
    const key = row.weather || "未知";
    grouped.set(key, (grouped.get(key) || 0) + 1);
  });
  return Array.from(grouped.entries()).sort((a, b) => b[1] - a[1])[0][0];
}

function getMapView(intersections) {
  if (!intersections.length) return MAP_DEFAULT;
  const lng = average(intersections.map((item) => item.longitude));
  const lat = average(intersections.map((item) => item.latitude));
  return { center: [lng, lat], zoom: 16.6 };
}

function App() {
  const [timeRange, setTimeRange] = useState({ min: "", max: "", current: "" });
  const [currentTime, setCurrentTime] = useState("");
  const [amapKey, setAmapKey] = useState("");
  const [intersections, setIntersections] = useState([]);
  const [routes, setRoutes] = useState([]);
  const [predictionOptions, setPredictionOptions] = useState([]);
  const [predictionMeta, setPredictionMeta] = useState(null);
  const [trafficRows, setTrafficRows] = useState([]);
  const [predictionRows, setPredictionRows] = useState([]);
  const [predictionCompare, setPredictionCompare] = useState(null);
  const [selectedSite, setSelectedSite] = useState("");
  const [selectedDirection, setSelectedDirection] = useState("");
  const [directionFilter, setDirectionFilter] = useState("全部方向");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [executedActions, setExecutedActions] = useState({});
  const [systemClock, setSystemClock] = useState(() => new Date());

  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const AMapRef = useRef(null);
  const overlaysRef = useRef([]);

  useEffect(() => {
    const timer = window.setInterval(() => setSystemClock(new Date()), 1000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    async function bootstrap() {
      setLoading(true);
      setError("");
      try {
        const [config, range, routeData, optionData, meta] = await Promise.all([
          fetchPublicConfig(),
          fetchDataRange(),
          fetchDirectionRoutes(),
          fetchPredictionOptions(),
          fetchPredictionMeta(),
        ]);
        setAmapKey(config.amap_api_key || "");
        setIntersections(config.intersections || []);
        setRoutes(routeData || []);
        setPredictionOptions(optionData || []);
        setPredictionMeta(meta);

        const min = toInputTime(range.min_timestamp);
        const max = toInputTime(range.max_timestamp);
        const initial = max;
        setTimeRange({ min, max, current: initial });
        setCurrentTime(initial);

        const defaultSite = optionData?.[0]?.site_name || config.intersections?.[0]?.site_name || "";
        const defaultDirection = optionData?.[0]?.directions?.[0] || "";
        setSelectedSite(defaultSite);
        setSelectedDirection(defaultDirection);
      } catch (bootstrapError) {
        setError(`初始化失败：${bootstrapError.message}`);
      } finally {
        setLoading(false);
      }
    }

    bootstrap();
  }, []);

  const activeDirections = useMemo(() => {
    const option = predictionOptions.find((item) => item.site_name === selectedSite);
    return option?.directions?.length ? option.directions : [];
  }, [predictionOptions, selectedSite]);

  useEffect(() => {
    if (!activeDirections.length) return;
    if (!activeDirections.includes(selectedDirection)) {
      setSelectedDirection(activeDirections[0]);
    }
  }, [activeDirections, selectedDirection]);

  useEffect(() => {
    if (!currentTime || !selectedSite || !selectedDirection) return;

    async function loadTrafficAndPrediction() {
      setLoading(true);
      setError("");
      try {
        const trafficParams = {
          start_time: toApiTime(addMinutes(currentTime, -60)),
          end_time: toApiTime(currentTime),
          limit: 2000,
        };
        if (directionFilter !== "全部方向") {
          trafficParams.direction = directionFilter;
        }

        const [trafficData, predictionData, compareData] = await Promise.all([
          fetchTraffic(trafficParams),
          fetchPrediction({
            time_range: toApiTime(currentTime),
            road_name: selectedSite,
            direction: selectedDirection,
          }),
          fetchPredictionCompare({
            time_range: toApiTime(currentTime),
            road_name: selectedSite,
            direction: selectedDirection,
          }),
        ]);

        setTrafficRows(trafficData || []);
        setPredictionRows(predictionData || []);
        setPredictionCompare(compareData);
      } catch (loadError) {
        setError(`数据加载失败：${loadError.message}`);
        setTrafficRows([]);
        setPredictionRows([]);
        setPredictionCompare(null);
      } finally {
        setLoading(false);
      }
    }

    loadTrafficAndPrediction();
  }, [currentTime, selectedSite, selectedDirection, directionFilter]);

  const siteSummaries = useMemo(
    () => buildSiteSummaries(trafficRows, intersections),
    [trafficRows, intersections]
  );

  useEffect(() => {
    if (!selectedSite && siteSummaries.length) {
      setSelectedSite(siteSummaries[0].siteName);
    }
  }, [selectedSite, siteSummaries]);

  const selectedSummary = useMemo(
    () => siteSummaries.find((item) => item.siteName === selectedSite) || siteSummaries[0],
    [selectedSite, siteSummaries]
  );

  const monitorRows = useMemo(() => buildMonitorRows(trafficRows), [trafficRows]);
  const predictionStats = useMemo(() => buildPredictionStats(predictionRows), [predictionRows]);
  const interventions = useMemo(
    () => buildInterventions(selectedSummary, selectedDirection, predictionStats),
    [selectedSummary, selectedDirection, predictionStats]
  );
  const predictionSeries = useMemo(() => buildPredictionSeries(predictionRows), [predictionRows]);
  const effectSeries = useMemo(
    () => buildEffectSeries(predictionRows, interventions),
    [predictionRows, interventions]
  );

  const weatherSummary = useMemo(() => getWeatherSummary(trafficRows), [trafficRows]);
  const topCards = useMemo(() => siteSummaries.slice(0, 4), [siteSummaries]);

  const kpis = useMemo(() => {
    const totalVehicle = trafficRows.reduce((sum, row) => sum + (Number(row.vehicle_count) || 0), 0);
    const avgSpeed = Number(average(trafficRows.map((row) => Number(row.avg_speed) || 0)).toFixed(1));
    const highRiskSites = siteSummaries.filter((item) => ["high", "critical"].includes(item.risk)).length;
    return {
      totalVehicle,
      avgSpeed,
      congestionSites: highRiskSites,
      alerts: interventions.length,
      selectedPeak: predictionStats.peak,
    };
  }, [trafficRows, siteSummaries, interventions, predictionStats]);

  useEffect(() => {
    if (!mapContainerRef.current || !intersections.length || !amapKey) return;
    let canceled = false;

    async function initMap() {
      if (mapRef.current || !mapContainerRef.current) return;
      try {
        const AMap = await AMapLoader.load({
          key: amapKey,
          version: "2.0",
          plugins: ["AMap.Scale"],
        });
        if (canceled) return;
        AMapRef.current = AMap;
        const view = getMapView(intersections);
        const map = new AMap.Map(mapContainerRef.current, {
          center: view.center,
          zoom: view.zoom,
          mapStyle: "amap://styles/darkblue",
          viewMode: "2D",
        });
        map.addControl(new AMap.Scale());
        mapRef.current = map;
      } catch (mapError) {
        setError(`地图加载失败：${mapError.message}`);
      }
    }

    initMap();
    return () => {
      canceled = true;
    };
  }, [amapKey, intersections]);

  useEffect(() => {
    if (!mapRef.current || !AMapRef.current) return;

    overlaysRef.current.forEach((item) => item.setMap(null));
    overlaysRef.current = [];

    const AMap = AMapRef.current;
    const riskMap = new Map(siteSummaries.map((item) => [item.siteName, item.risk]));

    intersections.forEach((site) => {
      const marker = new AMap.Marker({
        position: [site.longitude, site.latitude],
        offset: new AMap.Pixel(-10, -10),
        content: `
          <div class="command-marker ${selectedSite === site.site_name ? "active" : ""}">
            <span class="command-marker__pulse" style="background:${RISK_COLORS[riskMap.get(site.site_name) || "low"]}"></span>
          </div>
        `,
      });
      marker.on("click", () => setSelectedSite(site.site_name));
      marker.setMap(mapRef.current);
      overlaysRef.current.push(marker);
    });

    routes.forEach((route) => {
      const risk = riskMap.get(route.site_name) || "low";
      const highlighted = route.site_name === selectedSite && route.direction === selectedDirection;
      const polyline = new AMap.Polyline({
        path: route.path.map((point) => [point.longitude, point.latitude]),
        strokeColor: highlighted ? "#7dd3fc" : RISK_COLORS[risk],
        strokeWeight: highlighted ? 8 : 5,
        strokeOpacity: highlighted ? 0.95 : 0.7,
        lineCap: "round",
      });
      polyline.setMap(mapRef.current);
      overlaysRef.current.push(polyline);
    });
  }, [intersections, routes, selectedDirection, selectedSite, siteSummaries]);

  const executeIntervention = (actionId) => {
    setExecutedActions((prev) => ({ ...prev, [actionId]: "执行中" }));
    window.setTimeout(() => {
      setExecutedActions((prev) => ({ ...prev, [actionId]: "已下发" }));
    }, 900);
  };

  return (
    <div className="admin-shell">
      <header className="top-bar">
        <div>
          <div className="eyebrow">TRAFFIC COMMAND</div>
          <h1>城市路口交通干预决策系统</h1>
        </div>
        <div className="top-controls">
          <div className="clock-block">
            <span>系统时间</span>
            <strong>{formatFullTime(systemClock)}</strong>
          </div>
          <label className="control">
            <span>全局时间</span>
            <input
              type="datetime-local"
              min={timeRange.min}
              max={timeRange.max}
              value={currentTime}
              onChange={(event) => setCurrentTime(event.target.value)}
            />
          </label>
          <label className="control">
            <span>方向筛选</span>
            <select value={directionFilter} onChange={(event) => setDirectionFilter(event.target.value)}>
              <option value="全部方向">全部方向</option>
              {Array.from(new Set(monitorRows.map((item) => item.direction))).map((item) => (
                <option key={item} value={item}>
                  {item}
                </option>
              ))}
            </select>
          </label>
        </div>
      </header>

      <section className="quick-strip">
        {topCards.map((card) => (
          <button
            key={card.siteName}
            type="button"
            className={`quick-card ${selectedSite === card.siteName ? "active" : ""}`}
            onClick={() => setSelectedSite(card.siteName)}
          >
            <span className="quick-card__name">{card.siteName}</span>
            <strong>{card.avgVehicleCount}</strong>
            <small>平均车辆</small>
            <i style={{ backgroundColor: RISK_COLORS[card.risk] }} />
          </button>
        ))}
      </section>

      <section className="kpi-grid">
        <article className="kpi-card">
          <span>当前拥堵路口</span>
          <strong>{kpis.congestionSites}</strong>
        </article>
        <article className="kpi-card">
          <span>当前总车流量</span>
          <strong>{kpis.totalVehicle}</strong>
        </article>
        <article className="kpi-card">
          <span>平均车速</span>
          <strong>{kpis.avgSpeed} km/h</strong>
        </article>
        <article className="kpi-card">
          <span>干预建议数</span>
          <strong>{kpis.alerts}</strong>
        </article>
        <article className="kpi-card">
          <span>预测峰值</span>
          <strong>{kpis.selectedPeak}</strong>
        </article>
      </section>

      <main className="command-layout">
        <aside className="panel left-panel">
          <section className="panel-section">
            <div className="panel-title">
              <h2>实时监测</h2>
              <span>{loading ? "数据刷新中" : "已同步"}</span>
            </div>
            <div className="monitor-list">
              {monitorRows.slice(0, 6).map((item) => (
                <button
                  key={`${item.siteName}-${item.direction}`}
                  type="button"
                  className={`monitor-item ${selectedSite === item.siteName ? "active" : ""}`}
                  onClick={() => {
                    setSelectedSite(item.siteName);
                    setSelectedDirection(item.direction);
                  }}
                >
                  <div>
                    <strong>{item.siteName}</strong>
                    <span>{item.direction}</span>
                  </div>
                  <div className="monitor-item__stats">
                    <span>{item.avgVehicleCount} 辆</span>
                    <span>{item.avgSpeed} km/h</span>
                    <em style={{ color: RISK_COLORS[item.risk] }}>{riskLabel(item.risk)}</em>
                  </div>
                </button>
              ))}
            </div>
          </section>

          <section className="panel-section">
            <div className="panel-title">
              <h2>干预建议</h2>
              <span>{selectedSummary?.siteName || "未选中"}</span>
            </div>
            <div className="intervention-list">
              {interventions.map((item) => (
                <article key={item.id} className="intervention-card">
                  <div className="intervention-card__header">
                    <div>
                      <strong>{item.title}</strong>
                      <span>{item.target}</span>
                    </div>
                    <b>{item.priority}</b>
                  </div>
                  <p>{item.reason}</p>
                  <div className="intervention-card__footer">
                    <small>{item.expected}</small>
                    <button type="button" onClick={() => executeIntervention(item.id)}>
                      {executedActions[item.id] || "执行"}
                    </button>
                  </div>
                </article>
              ))}
            </div>
          </section>
        </aside>

        <section className="panel map-panel">
          <div className="panel-title">
            <h2>路网战情地图</h2>
            <span>{selectedSite || "未选中路口"}</span>
          </div>
          <div className="map-surface">
            <div ref={mapContainerRef} className="map-container" />
            {selectedSummary ? (
              <div className="map-overlay-card">
                <span>{selectedSummary.siteName}</span>
                <strong>{selectedSummary.avgVehicleCount} 辆</strong>
                <small>
                  {selectedDirection || selectedSummary.directions[0] || "主方向"} · {riskLabel(selectedSummary.risk)}
                </small>
              </div>
            ) : null}
          </div>
        </section>

        <aside className="panel right-panel">
          <section className="panel-section">
            <div className="panel-title">
              <h2>预测情报</h2>
              <span>{selectedDirection || "未指定方向"}</span>
            </div>
            <div className="prediction-meta">
              <div>
                <span>预测峰值</span>
                <strong>{predictionStats.peak}</strong>
              </div>
              <div>
                <span>低值</span>
                <strong>{predictionStats.low}</strong>
              </div>
              <div>
                <span>峰值时刻</span>
                <strong>{predictionStats.peakTime}</strong>
              </div>
              <div>
                <span>天气</span>
                <strong>{weatherSummary}</strong>
              </div>
            </div>
            <div className="chart-block">
              <ResponsiveContainer width="100%" height={240}>
                <AreaChart data={predictionSeries}>
                  <defs>
                    <linearGradient id="predictionFill" x1="0" x2="0" y1="0" y2="1">
                      <stop offset="0%" stopColor="#38bdf8" stopOpacity={0.45} />
                      <stop offset="100%" stopColor="#38bdf8" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid stroke="rgba(148,163,184,0.18)" vertical={false} />
                  <XAxis dataKey="time" tick={{ fill: "#94a3b8", fontSize: 11 }} />
                  <YAxis tick={{ fill: "#94a3b8", fontSize: 11 }} />
                  <Tooltip />
                  <Area
                    type="monotone"
                    dataKey="predicted"
                    stroke="#38bdf8"
                    fill="url(#predictionFill)"
                    strokeWidth={2.5}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
            <div className="compare-grid">
              <div>
                <span>模型</span>
                <strong>{predictionMeta?.model_type || "unavailable"}</strong>
              </div>
              <div>
                <span>测试 MAE</span>
                <strong>{predictionMeta?.test_mae ?? "--"}</strong>
              </div>
              <div>
                <span>误差回看 MAE</span>
                <strong>{predictionCompare?.mae ?? "--"}</strong>
              </div>
              <div>
                <span>误差回看 MAPE</span>
                <strong>{predictionCompare?.mape ? `${predictionCompare.mape}%` : "--"}</strong>
              </div>
            </div>
          </section>
        </aside>
      </main>

      <section className="panel bottom-panel">
        <div className="panel-title">
          <h2>干预效果评估</h2>
          <span>基于当前策略的模拟结果</span>
        </div>
        <div className="effect-summary">
          <article>
            <span>执行策略数</span>
            <strong>{Object.keys(executedActions).length}</strong>
          </article>
          <article>
            <span>预测均值</span>
            <strong>{predictionStats.avg}</strong>
          </article>
          <article>
            <span>模拟改善</span>
            <strong>
              {effectSeries.length
                ? `${Math.max(
                    0,
                    Math.round(
                      average(effectSeries.map((item) => item.before)) -
                        average(effectSeries.map((item) => item.after))
                    )
                  )} 辆`
                : "--"}
            </strong>
          </article>
        </div>
        <div className="effect-chart">
          <ResponsiveContainer width="100%" height={220}>
            <LineChart data={effectSeries}>
              <CartesianGrid stroke="rgba(148,163,184,0.18)" vertical={false} />
              <XAxis dataKey="time" tick={{ fill: "#94a3b8", fontSize: 11 }} />
              <YAxis tick={{ fill: "#94a3b8", fontSize: 11 }} />
              <Tooltip />
              <Line type="monotone" dataKey="before" stroke="#fb7185" strokeWidth={2.4} dot={false} />
              <Line type="monotone" dataKey="after" stroke="#22c55e" strokeWidth={2.4} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </section>

      {error ? <div className="status-banner error">{error}</div> : null}
      {!error && loading ? <div className="status-banner">数据同步中...</div> : null}
    </div>
  );
}

export default App;
